S(BK({"id": "bk_evid", "ic": "🔎", "name": "دلائل على تكوين باطن الأرض", "pg": "ص ١٦٤–١٦٥", "title": "دلائل على تكوين باطن الأرض", "cols": 2, "cards": [["الملاحظات غير المباشرة", ["كما نعرف ما في هدية مغلقة بحملها ورجّها ووزنها دون فتحها، يستخدم الجيولوجيون <b>الملاحظات غير المباشرة</b>.", "أعمق المناجم لا يمثل سوى <b>خدش</b> على سطح الأرض، والوصول إلى مركزها يتطلب حفر أكثر من <b>٦٠٠٠ كم</b>.", "لذا يجمعون الأدلة بدراسة <b>الزلازل</b> و<b>الصخور</b> المكشوفة على السطح."]], ["الأمواج", ["<b>الموجة</b>: اضطراب يحمل الطاقة عبر المادة أو الفراغ، كالأمواج حول حجر في بركة (الشكل ١).", "عند حدوث الزلازل تنتقل الطاقة بواسطة <b>الأمواج الزلزالية</b>.", "تعتمد سرعتها على <b>كثافة الوسط وطبيعته</b>؛ فهي أسرع في المواد الصلبة منها في السائلة، وقد تنحني أو تتوقف."]], ["أنواع الأمواج الزلزالية", ["<b>الأولية</b>: أسرعها، تنتقل في المواد الصلبة والسائلة والغازية، وتضاغط جسيمات الصخور في اتجاه حركتها.", "<b>الثانوية</b>: تنتقل في المواد <b>الصلبة فقط</b>، وتحرّك جسيمات الصخر عموديًّا على اتجاه حركتها.", "<b>السطحية</b>: أبطأ الأنواع، وتنتقل على سطح الأرض فقط."]], ["الأدلة الصخرية", ["صخور منتشرة في مواقع مختلفة على السطح تشبه في مكوناتها <b>مكونات باطن الأرض</b>.", "تكوّنت في الأعماق، ثم دُفعت إلى السطح أو قربه فتعرّضت للتعرية.", "تشير الأدلة <b>الزلزالية والصخرية</b> إلى أن الأرض مكونة من <b>طبقات</b> تختلف في مكوناتها."]]]}));
