S(BK({"id": "bk_struct", "ic": "📊", "name": "بنية الأرض", "pg": "ص ١٦٦", "title": "بنية الأرض", "cols": 3, "cards": [["تغيّر الخصائص مع العمق", ["يمكن تقسيم النطاقات الأربعة إلى نطاقات أخرى اعتمادًا على <b>تغيّر خصائصها الفيزيائية مع العمق</b>.", "من هذه الخصائص: <b>الكثافة، ودرجة الحرارة، والضغط</b>.", "تكون قيمها <b>أقل ما يمكن عند القشرة</b>، و<b>أكبر ما يمكن في اللب الداخلي</b>."]], ["توزيع كتلة الأرض (الشكل ٣)", ["<b>الستار</b> نحو <b>٦٧٪</b> من كتلة الأرض.", "<b>اللب الخارجي</b> نحو <b>٣٠٪</b>.", "<b>اللب الداخلي</b> نحو <b>٢٫٥٪</b>، و<b>القشرة</b> نحو <b>٠٫٥٪</b>."]], ["القشرة والغلافان", ["تنقسم القشرة إلى <b>قشرة محيطية</b> تحت المحيطات و<b>قشرة قارية</b> تحت القارات.", "القشرة مع الجزء العلوي من الستار تكوّن <b>الغلاف الصخري</b>، وتحته <b>الغلاف اللدن</b>."]]]}));
S(BK({"id": "bk_plates", "ic": "🧩", "name": "صفائح الأرض", "pg": "ص ١٦٧", "title": "صفائح الأرض", "cols": 2, "cards": [["الغلاف الصخري", ["على الرغم من انفصال القشرة عن الستار، فإن <b>الجزء العلوي المتماسك من الستار</b> يتحرك كأنه جزء من القشرة.", "يكوّن الجزء العلوي من الستار مع القشرة ما يُسمّى <b>الغلاف الصخري</b>."]], ["الصفائح الأرضية", ["يتجزأ الغلاف الصخري إلى نحو <b>٣٠ قطعة</b>، كلٌّ منها <b>صفيحة أرضية</b>.", "تتحرك الصفائح فوق <b>الغلاف اللدن</b> (جزء من الستار)، وتختلف في الحجم والشكل (الشكل ٤)، ومنها <b>الصفيحة العربية</b>."], ["p_plates"]], ["حركة الصفائح", ["تتحرك ببطء؛ تزحف الصفيحة <b>بضعة سنتيمترات في السنة</b>، فهيئة الصفائح ليست ثابتة.", "تحركت القارات مسافات شاسعة: كانت القارة القطبية الجنوبية عند <b>خط الاستواء</b>، وكانت أمريكا الشمالية متصلة <b>بأوروبا وإفريقيا</b>."]], ["قياس حركة الصفائح", ["تُستخدم <b>أشعة الليزر</b> و<b>صور الأقمار الاصطناعية</b> لقياس حركة الصفائح الصغيرة التي تصبح مسافات كبيرة مع الزمن.", "صفيحة تتحرك <b>٢ سم</b> في السنة تقطع <b>٢٠ م</b> في ١٠٠٠ سنة، و<b>٢٠٠ كم</b> في ١٠ ملايين سنة."]]]}));
S(BK({"id": "bk_bound1", "ic": "↔", "name": "حدود الصفائح والصفائح المتباعدة", "pg": "ص ١٦٨–١٦٩", "title": "حدود الصفائح: الصفائح المتباعدة", "cols": 2, "cards": [["حدود الصفائح", ["مناطق التقاء الصفائح تُسمّى <b>حدود الصفائح</b>، وتولّد حركتها الدائمة قوى تؤثر في سطح الأرض.", "في بعض الحدود تكون القوى كبيرة فتتكوّن <b>الجبال</b>، وفي أخرى تتكوّن <b>حفر انهدام</b> ضخمة ذات نشاطات بركانية."]], ["الصدوع", ["<b>الصدوع</b>: كسور كبيرة في الصخور بفعل حركة الصفائح، ويمكن أن تسبّب حدوث <b>الزلازل</b>.", "تتحرك الصفائح: <b>متقاربة</b>، أو <b>متباعدة</b>، أو <b>متحاذية</b> (الشكل ٥)."]], ["الصفائح المتباعدة", ["تتحرك متباعدة نتيجة <b>قوى الشد</b> في اتجاهين متعاكسين.", "تتكوّن <b>قشرة جديدة</b> في الفجوات؛ إذ تمتلئ تدريجيًّا بالصهارة المندفعة من الستار ثم تبرد.", "القشرة الجديدة أقل كثافة من الصخور المحيطة؛ لذا تكوّن في الغالب <b>ظهرًا مرتفعًا</b>."]], ["الوديان الخسفية (الشكل ٦)", ["١) تندفع الصهارة فتتشقق القشرة. ٢) تنزل ألواح صخرية فيتكوّن <b>نطاق انهدام</b>.", "٣) مع زيادة التباعد يتكوّن <b>بحر ضيق أو بحيرة</b>. ٤) في النهاية <b>حوض محيط وظهر محيط</b>.", "يمتد الانهدام العظيم في <b>شرق إفريقيا</b> مسافة <b>٥٦٠٠ كم</b>."]]]}));
S(BK({"id": "bk_bound2", "ic": "⇄", "name": "الصفائح المتقاربة والمتحاذية", "pg": "ص ١٧٠–١٧١", "title": "الصفائح المتقاربة، وغوص الصفائح، والصفائح المتحاذية", "cols": 2, "cards": [["الصفائح المتقاربة", ["تتحرك الصفائح وتتصادم، فتُسمّى حدودها <b>حدودًا تصادمية</b>.", "تعتمد نتيجة الاصطدام على <b>كثافة</b> كل صفيحة؛ والقشرة <b>المحيطية</b> أكثر كثافة من القشرة <b>القارية</b>."]], ["أنواع التقارب (الشكل ٧)", ["<b>محيطي–محيطي</b>: تغوص الأعلى كثافة، فتتكوّن <b>أخاديد</b> عميقة وتتدفق اللابة مكوّنة <b>جزرًا</b>.", "<b>محيطي–قاري</b>: تنزلق المحيطية الأكثر كثافة أسفل القارية مكوّنة <b>البراكين</b>.", "<b>قاري–قاري</b>: كثافتهما متساوية، فتنطوي الصخور وتلتوي مكوّنة <b>سلاسل جبلية</b> مثل <b>الهملايا</b>."]], ["غوص الصفائح", ["عندما تقترب صفيحة محيطية من صفيحة محيطية أو قارية، تنثني <b>الأكثر كثافة</b> أسفل الأخرى وتغطس في الستار: <b>غوص الصفائح</b>.", "لذلك لا تستمر القشرة في النمو؛ فمع تكوّن قشرة جديدة في مناطق الانهدام تغطس القشرة القديمة في الستار."]], ["الصفائح المتحاذية", ["تتحرك صفيحتان في اتجاهين متعاكسين بمحاذاة بعضهما، وتُسمّى الحدود بينهما <b>تحويلية</b>.", "تنشأ <b>قوى القص</b> فتسبّب الزلازل والصدوع في منطقة التماس (الشكل ٨).", "من الأمثلة: منطقة <b>البحر الميت</b>."]]]}));
